import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {

  const videoRef = useRef(null);
  const streamRef = useRef(null);

  const [cameraActive, setCameraActive] = useState(false);
  const [loading, setLoading] = useState(false);

  const [error, setError] = useState(null);
  const [logs, setLogs] = useState([]);

  const [lastResult, setLastResult] = useState(null);

  // ================= LOG SYSTEM =================
  const log = (msg, type = "info") => {
    console.log(`[CAMERA][${type.toUpperCase()}]`, msg);
    setLogs(prev => [...prev.slice(-20), { msg, type, time: new Date().toLocaleTimeString() }]);
  };

  // ================= START CAMERA =================
  const startCamera = async () => {
    setLoading(true);
    setError(null);

    log("Initialisation caméra...");

    try {
      // ⚠️ CHECK API SUPPORT
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("getUserMedia non supporté par ce navigateur");
      }

      log("Demande permission caméra...");

      // 🎥 CAMERA STREAM
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          facingMode: "user"
        },
        audio: false
      });

      log("Stream caméra obtenu", "success");

      streamRef.current = stream;

      if (!videoRef.current) {
        throw new Error("Video ref introuvable");
      }

      videoRef.current.srcObject = stream;

      videoRef.current.onloadedmetadata = async () => {
        try {
          await videoRef.current.play();
          setCameraActive(true);
          setLoading(false);
          log("Caméra active et lecture vidéo OK", "success");

          if (addNotification) {
            addNotification("Caméra activée", "success");
          }

        } catch (playErr) {
          log("Erreur lecture vidéo: " + playErr.message, "error");
          setError("Impossible de lancer la vidéo");
        }
      };

    } catch (err) {

      log(err.message, "error");

      let message = "Erreur caméra";

      if (err.name === "NotAllowedError") {
        message = "Permission caméra refusée";
      } else if (err.name === "NotFoundError") {
        message = "Aucune caméra détectée";
      } else if (err.name === "NotReadableError") {
        message = "Caméra déjà utilisée par une autre application";
      } else {
        message = err.message;
      }

      setError(message);
      setCameraActive(false);

      if (addNotification) {
        addNotification(message, "error");
      }

    } finally {
      setLoading(false);
    }
  };

  // ================= STOP CAMERA =================
  const stopCamera = () => {
    log("Arrêt caméra");

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        log(`Track stoppé: ${track.kind}`);
      });
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraActive(false);
  };

  // ================= CAPTURE =================
  const captureFrame = async () => {
    if (!videoRef.current) return;

    try {
      const canvas = document.createElement("canvas");
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;

      const ctx = canvas.getContext("2d");
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL("image/jpeg", 0.9);

      log("Image capturée, envoi backend...");

      const res = await attendanceAPI.recognize(imageBase64);
      const data = res?.data;

      if (!data) {
        throw new Error("Réponse backend vide");
      }

      log("Réponse backend reçue", "success");

      setLastResult(data);

    } catch (err) {
      log("Erreur capture: " + err.message, "error");
      setError("Erreur reconnaissance: " + err.message);
    }
  };

  // ================= CLEANUP =================
  useEffect(() => {
    return () => {
      stopCamera();
      log("Composant démonté");
    };
  }, []);

  // ================= UI =================
  return (
    <div style={styles.container}>

      <h2>📷 Reconnaissance Faciale</h2>

      {/* VIDEO */}
      <div style={styles.videoBox}>
        {cameraActive ? (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            style={styles.video}
          />
        ) : (
          <div style={styles.placeholder}>
            Caméra inactive
          </div>
        )}
      </div>

      {/* BUTTONS */}
      <div style={styles.buttons}>
        {!cameraActive ? (
          <button onClick={startCamera} disabled={loading}>
            {loading ? "Démarrage..." : "Démarrer caméra"}
          </button>
        ) : (
          <>
            <button onClick={captureFrame}>
              Capturer
            </button>

            <button onClick={stopCamera}>
              Arrêter
            </button>
          </>
        )}
      </div>

      {/* ERROR */}
      {error && (
        <div style={styles.error}>
          ❌ {error}
        </div>
      )}

      {/* RESULT */}
      {lastResult && (
        <div style={styles.result}>
          <h3>Résultat</h3>
          <p>Étudiant: {lastResult.student || "Inconnu"}</p>
          <p>Confiance: {(lastResult.confidence * 100).toFixed(1)}%</p>
        </div>
      )}

      {/* LOGS */}
      <div style={styles.logs}>
        <h4>Logs debug</h4>
        {logs.map((l, i) => (
          <div key={i} style={{ fontSize: 12 }}>
            [{l.time}] {l.type}: {l.msg}
          </div>
        ))}
      </div>

    </div>
  );
};

// ================= STYLES =================
const styles = {
  container: { padding: 20, fontFamily: "Arial" },

  videoBox: {
    width: "100%",
    height: 400,
    background: "#000",
    borderRadius: 10,
    overflow: "hidden",
    marginBottom: 10
  },

  video: {
    width: "100%",
    height: "100%",
    objectFit: "cover"
  },

  placeholder: {
    color: "white",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "100%"
  },

  buttons: {
    display: "flex",
    gap: 10,
    marginBottom: 10
  },

  error: {
    background: "#FEE2E2",
    padding: 10,
    color: "#991B1B",
    marginTop: 10,
    borderRadius: 6
  },

  result: {
    marginTop: 10,
    padding: 10,
    background: "#DCFCE7",
    borderRadius: 6
  },

  logs: {
    marginTop: 20,
    background: "#F1F5F9",
    padding: 10,
    borderRadius: 6,
    fontSize: 12
  }
};

export default CameraRecognition;
